(() => {
'use strict';
const CONFIG={apiUrl:'https://script.google.com/macros/s/AKfycbymM6uWOii_haTHKrprPLn0MXuGCIc2BP_Z8zowkT3LQ4yNBQYzBDId2_jVCf7dquA/exec'};
const SESSION_KEYS={parent:'eduwave_parent_session',admin:'eduwave_admin_session'};
const MAX_UPLOAD_BYTES=8*1024*1024;
const $=(s,p=document)=>p.querySelector(s),$$=(s,p=document)=>[...p.querySelectorAll(s)];
const state={sessionId:'',parent:null,dashboard:null,activeChild:'',admin:null,driveItems:[],driveFolders:null,driveFolderId:'',driveFolderQuery:'',familyQuery:'',auth:{parentEmail:'',adminEmail:''}};
let lastDialogTrigger=null;

document.addEventListener('DOMContentLoaded',init);
function init(){
  const year=$('#year');
  if(year)year.textContent=new Date().getFullYear();

  const navToggle=$('.nav-toggle');
  const siteNav=$('#site-nav');
  if(navToggle && siteNav){
    navToggle.addEventListener('click',()=>{
      const expanded=navToggle.getAttribute('aria-expanded')==='true';
      navToggle.setAttribute('aria-expanded',String(!expanded));
      navToggle.setAttribute('aria-label',expanded?'Open navigation':'Close navigation');
      siteNav.classList.toggle('open');
    });
    $$('#site-nav a').forEach(a=>a.addEventListener('click',()=>{
      navToggle.setAttribute('aria-expanded','false');
      navToggle.setAttribute('aria-label','Open navigation');
      siteNav.classList.remove('open');
    }));
  }

  if('IntersectionObserver' in window){
    const observer=new IntersectionObserver((entries,ob)=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');ob.unobserve(entry.target)}}),{threshold:.1,rootMargin:'0px 0px -40px'});
    $$('.reveal').forEach(el=>observer.observe(el));
  }else $$('.reveal').forEach(el=>el.classList.add('visible'));

  $$('[data-open-portal]').forEach(b=>b.addEventListener('click',()=>openDialog('portal-dialog',b)));
  $$('[data-open-admin]').forEach(b=>b.addEventListener('click',()=>openDialog('admin-dialog',b)));
  $$('[data-close-dialog]').forEach(b=>b.addEventListener('click',()=>closeDialog(b.closest('dialog'))));
  $('[data-close-viewer]')?.addEventListener('click',()=>closeDialog($('#viewer-dialog')));
  $$('dialog').forEach(dialog=>{
    dialog.addEventListener('click',event=>{if(event.target===dialog)closeDialog(dialog)});
    dialog.addEventListener('close',syncDialogState);
  });

  $('#trial-form')?.addEventListener('submit',trial);
  $$('[data-parent-auth]').forEach(b=>b.addEventListener('click',()=>parentAuthMode(b.dataset.parentAuth)));
  $('#parent-login-form')?.addEventListener('submit',e=>requestLoginCode(e,'parent'));
  $('#parent-signup-form')?.addEventListener('submit',signupParent);
  $('#parent-code-form')?.addEventListener('submit',e=>verifyLoginCode(e,'parent'));
  $('#admin-login-form')?.addEventListener('submit',e=>requestLoginCode(e,'admin'));
  $('#admin-code-form')?.addEventListener('submit',e=>verifyLoginCode(e,'admin'));
  $$('[data-reset-auth]').forEach(b=>b.addEventListener('click',()=>resetAuth(b.dataset.resetAuth)));
  $('#parent-logout')?.addEventListener('click',parentLogout);
  $('#admin-logout')?.addEventListener('click',adminLogout);
  $('#notification-button')?.addEventListener('click',toggleNotifications);
  $('#admin-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-admin-tab]');if(!b)return;$$('#admin-tabs button').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',String(x===b))});adminPanel(b.dataset.adminTab)});

  $$('img').forEach(img=>{
    img.addEventListener('error',()=>{
      img.style.display='none';
      const fallback=img.nextElementSibling;
      if(fallback && fallback.classList.contains('img-fallback'))fallback.style.display='flex';
    });
  });

  $$('form').forEach(form=>{
    form.addEventListener('submit',e=>{
      if(!form.checkValidity()){
        e.preventDefault();
        e.stopPropagation();
        const firstInvalid=form.querySelector(':invalid');
        if(firstInvalid){
          firstInvalid.focus();
          firstInvalid.scrollIntoView({behavior:'smooth',block:'center'});
        }
      }
      form.classList.add('was-validated');
    });
  });
  restoreSessions();
}
function openDialog(id,trigger){const dialog=$('#'+id);if(!dialog||dialog.open)return;lastDialogTrigger=trigger||document.activeElement;dialog._returnFocus=lastDialogTrigger;dialog.showModal();document.body.classList.add('dialog-open')}
function closeDialog(dialog){if(dialog?.open)dialog.close()}
function syncDialogState(event){
  const dialog=event?.currentTarget;
  dialog?._returnFocus?.focus?.();
  if(dialog)dialog._returnFocus=null;
  if(!$$('dialog[open]').length){document.body.classList.remove('dialog-open');lastDialogTrigger=null}
}
function toggleNotifications(){const panel=$('#notification-panel'),button=$('#notification-button');if(!panel||!button)return;const opening=panel.classList.contains('hidden');panel.classList.toggle('hidden',!opening);button.setAttribute('aria-expanded',String(opening))}
function clean(s){return String(s||'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function mimeFromName(name){const ext=String(name||'').toLowerCase().split('.').pop(),types={pdf:'application/pdf',jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',doc:'application/msword',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',xls:'application/vnd.ms-excel',xlsx:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',ppt:'application/vnd.ms-powerpoint',pptx:'application/vnd.openxmlformats-officedocument.presentationml.presentation',rtf:'application/rtf',txt:'text/plain'};return types[ext]||''}
async function encodeFile(file){if(!(file instanceof File)||!file.size)throw new Error('Choose a file first.');if(file.size>MAX_UPLOAD_BYTES)throw new Error('Choose a file smaller than 8 MB.');const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('The selected file could not be read.'));reader.readAsDataURL(file)});return{name:file.name,mimeType:file.type||mimeFromName(file.name),size:file.size,data:String(dataUrl).split(',')[1]||''}}
function date(v){if(!v)return'Not set';const d=new Date(v);return isNaN(d)?v:d.toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})}
function setStatus(el,text='',type=''){if(!el)return;el.textContent=text;el.className='form-status '+type}
function setBusy(button,busy,label='Working...'){if(!button)return;if(busy){button.dataset.label=button.innerHTML;button.innerHTML=label;button.disabled=true;button.classList.add('is-busy')}else{button.innerHTML=button.dataset.label||button.innerHTML;button.disabled=false;button.classList.remove('is-busy');delete button.dataset.label}}
function notify(message,type='success'){
  const region=$('#toast-region');if(!region)return;
  const toast=document.createElement('div');toast.className='toast '+type;
  const text=document.createElement('p');text.textContent=message;
  const close=document.createElement('button');close.type='button';close.setAttribute('aria-label','Dismiss message');close.textContent='x';
  close.addEventListener('click',()=>toast.remove());toast.append(text,close);region.append(toast);
  setTimeout(()=>toast.remove(),5000);
}
function device(){let id=localStorage.getItem('eduwave_device');if(!id){id=crypto.randomUUID?crypto.randomUUID():Date.now()+'';localStorage.setItem('eduwave_device',id)}return id}
async function api(action,payload={}){if(CONFIG.apiUrl.startsWith('YOUR_'))throw new Error('The portal API URL has not been configured.');const r=await fetch(CONFIG.apiUrl,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action,...payload})});const data=await r.json();if(!data.ok){if(data.message==='Unknown action.'&&/LoginCode|signupParent/.test(action))throw new Error('The email-login backend is not deployed yet. Update Apps Script to version 3.0, run setupEduwave, and deploy a new version.');throw new Error(data.message||'Request failed')}return data.data}
async function trial(e){e.preventDefault();const form=e.currentTarget,target=$('#trial-status'),button=form.querySelector('[type="submit"]');if(!form.reportValidity())return;setStatus(target,'Sending your request...');setBusy(button,true,'Sending request...');try{await api('submitTrial',Object.fromEntries(new FormData(form)));form.reset();form.classList.remove('was-validated');const message='Request received. The academy will confirm a slot.';setStatus(target,message,'success');notify(message)}catch(err){setStatus(target,err.message,'error');notify(err.message,'error')}finally{setBusy(button,false)}}
function parentAuthMode(mode){const login=mode!=='signup';$$('[data-parent-auth]').forEach(b=>{const active=b.dataset.parentAuth===(login?'login':'signup');b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active))});$('#parent-login-form').classList.toggle('hidden',!login);$('#parent-signup-form').classList.toggle('hidden',login);$('#parent-code-form').classList.add('hidden');$('.auth-switch',$('#portal-auth')).classList.remove('hidden');setStatus($('#portal-auth-status'))}
async function signupParent(e){e.preventDefault();const form=e.currentTarget,target=$('#portal-auth-status'),button=form.querySelector('[type="submit"]');if(!form.reportValidity())return;setStatus(target,'Submitting your access request...');setBusy(button,true,'Submitting request...');try{const values=Object.fromEntries(new FormData(form));await api('signupParent',values);form.reset();parentAuthMode('login');$('#parent-login-form [name="email"]').value=values.email;const message='Request received. The academy will approve your email before your first login.';setStatus(target,message,'success');notify(message)}catch(err){setStatus(target,err.message,'error');notify(err.message,'error')}finally{setBusy(button,false)}}
async function requestLoginCode(e,role){e.preventDefault();const form=e.currentTarget,target=$(role==='parent'?'#portal-auth-status':'#admin-auth-status'),button=form.querySelector('[type="submit"]');if(!form.reportValidity())return;const email=String(new FormData(form).get('email')||'').trim().toLowerCase();setStatus(target,'Preparing your secure code...');setBusy(button,true,'Sending code...');try{await api('requestLoginCode',{role,email,deviceId:device()});state.auth[role+'Email']=email;showCodeStep(role,email);setStatus(target,'If this email is approved, the code will arrive shortly. It expires in 10 minutes.','success')}catch(err){setStatus(target,err.message,'error');notify(err.message,'error')}finally{setBusy(button,false)}}
function maskEmail(value){const parts=String(value||'').split('@');if(parts.length!==2)return'approved inbox';const name=parts[0],domain=parts[1].split('.'),maskedName=name.slice(0,1)+'***',maskedDomain=(domain[0]?.slice(0,1)||'')+'***'+(domain.length>1?'.'+domain.slice(1).join('.'):'');return maskedName+'@'+maskedDomain}
function showCodeStep(role,email){if(role==='parent'){$('#parent-login-form').classList.add('hidden');$('#parent-signup-form').classList.add('hidden');$('.auth-switch',$('#portal-auth')).classList.add('hidden')}else $('#admin-login-form').classList.add('hidden');const form=$(role==='parent'?'#parent-code-form':'#admin-code-form');form.classList.remove('hidden');$('#'+role+'-code-email').textContent=maskEmail(email);setTimeout(()=>form.elements.code.focus(),0)}
async function verifyLoginCode(e,role){e.preventDefault();const form=e.currentTarget,target=$(role==='parent'?'#portal-auth-status':'#admin-auth-status'),button=form.querySelector('[type="submit"]');if(!form.reportValidity())return;const email=state.auth[role+'Email'],code=String(new FormData(form).get('code')||'').trim();setStatus(target,'Verifying the code...');setBusy(button,true,'Verifying...');try{const data=await api('verifyLoginCode',{role,email,code,deviceId:device(),deviceLabel:navigator.platform||'Browser'});form.reset();if(role==='parent')applyParent(data);else{state.admin={sessionId:data.sessionId,data:data.dashboard};sessionStorage.setItem(SESSION_KEYS.admin,data.sessionId);applyAdmin()}}catch(err){setStatus(target,err.message,'error');notify(err.message,'error')}finally{setBusy(button,false)}}
function resetAuth(role){state.auth[role+'Email']='';setStatus($(role==='parent'?'#portal-auth-status':'#admin-auth-status'));if(role==='parent'){$('#parent-code-form').classList.add('hidden');$('#parent-login-form').classList.remove('hidden');$('.auth-switch',$('#portal-auth')).classList.remove('hidden')}else{$('#admin-code-form').classList.add('hidden');$('#admin-login-form').classList.remove('hidden')}}
async function restoreSessions(){const parentToken=sessionStorage.getItem(SESSION_KEYS.parent),adminToken=sessionStorage.getItem(SESSION_KEYS.admin);if(parentToken)try{const d=await api('parentDashboard',{sessionId:parentToken});applyParent({sessionId:parentToken,parent:d.parent,dashboard:d.dashboard})}catch(_){sessionStorage.removeItem(SESSION_KEYS.parent)}if(adminToken)try{state.admin={sessionId:adminToken,data:await api('adminDashboard',{sessionId:adminToken})};applyAdmin()}catch(_){sessionStorage.removeItem(SESSION_KEYS.admin);state.admin=null}}
function applyParent(data){state.sessionId=data.sessionId;state.parent=data.parent;state.dashboard=data.dashboard;state.activeChild=data.dashboard.children[0]?.student_id||'';sessionStorage.setItem(SESSION_KEYS.parent,data.sessionId);$('#portal-auth').classList.add('hidden');$('#parent-app').classList.remove('hidden');$('#parent-greeting').textContent=`Hello, ${data.parent.name.split(' ')[0]}`;renderParent();const hasUpdates=data.dashboard.notifications.length>0;$('#notification-panel').classList.toggle('hidden',!hasUpdates);$('#notification-button').setAttribute('aria-expanded',String(hasUpdates));if(hasUpdates)notify(`${data.dashboard.notifications.length} update${data.dashboard.notifications.length===1?'':'s'} waiting in the parent portal.`)}
async function parentLogout(){try{await api('logout',{sessionId:state.sessionId})}catch(_){ }sessionStorage.removeItem(SESSION_KEYS.parent);state.sessionId='';state.parent=null;state.dashboard=null;state.activeChild='';$('#parent-app').classList.add('hidden');$('#portal-auth').classList.remove('hidden');$('#notification-panel').classList.add('hidden');$('#notification-button').setAttribute('aria-expanded','false');resetAuth('parent');closeDialog($('#portal-dialog'))}
function child(){return state.dashboard.children.find(x=>x.student_id===state.activeChild)}
function renderParent(){const children=state.dashboard.children,active=child();$('#child-tabs').innerHTML=children.map(x=>`<button type="button" role="tab" aria-selected="${x.student_id===state.activeChild}" class="${x.student_id===state.activeChild?'active':''}" data-child="${clean(x.student_id)}">${clean(x.name)} <small>(Class ${clean(x.class_level)})</small></button>`).join('');$$('[data-child]').forEach(b=>b.addEventListener('click',()=>{state.activeChild=b.dataset.child;renderParent()}));const notes=state.dashboard.notifications.filter(n=>!n.student_id||n.student_id===state.activeChild);$('#notification-count').textContent=notes.length;$('#notification-panel').innerHTML=notes.length?notes.map(n=>`<div class="notification"><b>${clean(n.type)}</b><strong>${clean(n.title)}</strong><br>${clean(n.message)}</div>`).join(''):'<div class="notification">No updates right now.</div>';if(!active){$('#parent-dashboard').innerHTML='<div class="notice">No child is linked to this approved parent account.</div>';return}
 const resources=active.resources.length?active.resources.map(r=>{const status=r.submission_status||'pending',label=status==='pending'?(r.due_date?`Due ${date(r.due_date)}`:'To do'):status.replace('_',' ');return`<div class="resource-row"><button type="button" data-resource="${clean(r.resource_id)}"><span>${clean(r.title)}</span><small>${clean(r.subject||'Learning material')} &#8250; ${clean(r.kind)} &#8250; ${r.submission_type==='file_upload'?'Upload completed work':'Open assignment'}</small></button><span class="status-pill ${clean(status)}">${clean(label)}</span></div>`}).join(''):'<div class="notice">The academy has not assigned material yet.</div>';
 const fees=active.fees.length?active.fees.map(f=>`<div class="fee-row"><div><b>Rs ${clean(f.amount)} &#8250; ${clean(f.billing_month)}</b><small>Due ${clean(date(f.due_date))}${f.reference?` &#8250; Ref ${clean(f.reference)}`:''}</small></div><span class="status-pill ${clean(f.status)}">${clean(f.status.replace('_',' '))}</span>${f.status!=='paid'?`<button class="text-button" data-pay="${clean(f.fee_id)}">Pay note</button>`:''}</div>`).join(''):'<div class="notice">No fee record is due right now.</div>';
 const attendance=active.attendance.length?active.attendance.map(x=>`<div class="attendance-row"><div><b>${clean(x.subject)}</b><small>${clean(date(x.session_date))}${x.note?` &#8250; ${clean(x.note)}`:''}</small></div><span class="status-pill ${clean(x.status)}">${clean(x.status)}</span></div>`).join(''):'<div class="notice">Attendance updates will appear here.</div>';
 const progress=active.progress.length?active.progress.map(x=>`<div class="progress-row"><div><b>${clean(x.topic)}</b><small>${clean(x.subject)}${x.teacher_note?` &#8250; ${clean(x.teacher_note)}`:''}</small></div><span class="status-pill">${clean(x.score||'noted')}</span></div>`).join(''):'<div class="notice">Progress notes will appear here.</div>';
 $('#parent-dashboard').innerHTML=`<section class="dashboard-hero"><div><p>CLASS ${clean(active.class_level)}</p><h3>${clean(active.name)}&#8217;s learning space</h3><p>${active.resources.length} learning item${active.resources.length===1?'':'s'} currently available.</p></div><button class="button button-dark" id="quick-updates" type="button">View ${notes.length} update${notes.length===1?'':'s'}</button></section><div class="dashboard-grid"><section class="dash-card"><h4>Assignments & materials</h4><div class="resource-list">${resources}</div></section><section class="dash-card"><h4>Fee status</h4><div class="fee-list">${fees}</div></section></div><div class="two-cards"><section class="dash-card"><h4>Recent attendance</h4><div class="attendance-list">${attendance}</div></section><section class="dash-card"><h4>Teacher notes & progress</h4><div class="progress-list">${progress}</div></section></div>`;
 $('#quick-updates').addEventListener('click',toggleNotifications);$$('[data-resource]').forEach(b=>b.addEventListener('click',()=>resource(b.dataset.resource,b)));$$('[data-pay]').forEach(b=>b.addEventListener('click',()=>payment(b.dataset.pay)));
}
function worksheetTable(view){const answerMode=view.submissionType==='online_answers',saved=new Map((view.submission?.answers||[]).map(x=>[Number(x.row),x.answer])),rows=view.values||[],head=rows[0]||[];return`<div class="worksheet-table-wrap"><table class="viewer-table worksheet-table"><thead><tr>${head.map(c=>`<th>${clean(c)}</th>`).join('')}${answerMode?'<th>Your answer</th>':''}</tr></thead><tbody>${rows.slice(1).map((r,index)=>{const row=index+2,question=r.filter(Boolean).join(' | ')||`Question ${index+1}`;return`<tr>${r.map(c=>`<td>${clean(c)}</td>`).join('')}${answerMode?`<td><input class="worksheet-answer" data-row="${row}" data-question="${clean(question)}" value="${clean(saved.get(row)||'')}" aria-label="Answer for row ${row}" placeholder="Type your answer"></td>`:''}</tr>`}).join('')}</tbody></table></div>`}
function submissionPanel(view){
  if(view.submissionType==='view_only')return'<div class="notice assignment-note">This is reference material. Nothing needs to be submitted.</div>';
  const sub=view.submission,status=sub?.status||'pending',locked=status==='reviewed',fileMode=view.submissionType==='file_upload',statusText=status==='pending'?'Not submitted':status.replace('_',' '),feedback=sub?.feedback?`<div class="teacher-feedback"><b>Teacher feedback</b><p>${clean(sub.feedback)}</p></div>`:'';
  const upload=fileMode?`<label class="upload-field"><span class="upload-icon" aria-hidden="true">&#8593;</span><span><b>${sub?.has_attachment?'Replace submitted scan':'Add completed work'}</b><small>PDF, JPG, or PNG, up to 8 MB. Use your phone camera or a scanner.</small>${sub?.has_attachment?`<em>Current file: ${clean(sub.attachment_name)}</em>`:''}</span><input name="attachment" type="file" accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png" ${sub?.has_attachment?'':'required'} ${locked?'disabled':''}></label>`:'';
  const guidance=fileMode?'Answer in a notebook, scan every completed page clearly, then upload one PDF or image.':'Type answers directly in the worksheet below. Your work is stored in Eduwave, not in the academy master Sheet.';
  return`<section class="submission-card"><div class="submission-heading"><div><p class="eyebrow">Send to teacher</p><h3>${fileMode?'Upload completed work':'Complete and submit'}</h3></div><span class="status-pill ${clean(status)}">${clean(statusText)}</span></div><p>${guidance}${view.dueDate?` Due ${clean(date(view.dueDate))}.`:''}</p>${feedback}<form id="assignment-submit-form">${upload}<label class="field"><span>Message for the teacher <small>optional</small></span><textarea name="note" rows="3" placeholder="Mention any question you found difficult" ${locked?'disabled':''}>${clean(sub?.student_note||'')}</textarea></label><button class="button button-ink" type="submit" ${locked?'disabled':''}>${locked?'Reviewed by teacher':sub?(fileMode?'Update submitted work':'Resend updated work'):(fileMode?'Send completed work':'Submit worksheet')}</button><p class="form-status" role="status" aria-live="polite">${sub?`Last sent ${clean(date(sub.submitted_at))}.`:''}</p></form></section>`;
}
async function submitAssignment(event,view,studentId){event.preventDefault();const form=event.currentTarget,out=$('.form-status',form),button=form.querySelector('[type="submit"]'),answers=$$('.worksheet-answer',$('#viewer-content')).map(input=>({row:Number(input.dataset.row),question:input.dataset.question,answer:input.value.trim()})).filter(x=>x.answer);setStatus(out,'Sending your work...');setBusy(button,true,'Sending...');try{const file=$('[name="attachment"]',form)?.files?.[0],attachment=file?await encodeFile(file):null;await api('parentSubmitAssignment',{sessionId:state.sessionId,studentId,assignmentId:view.assignmentId,answers,note:new FormData(form).get('note'),attachment});setBusy(button,false);button.textContent='Submitted';setStatus(out,'Submitted. Your teacher can now review it.','success');notify('Work submitted to the academy.');$$('input, textarea, button',form.closest('.submission-card')).forEach(x=>x.disabled=true);$$('.worksheet-answer',$('#viewer-content')).forEach(x=>x.disabled=true);await refreshParent()}catch(err){setStatus(out,err.message,'error');notify(err.message,'error');setBusy(button,false)}}
function secureFileBody(view){if(view.kind==='text')return`<div class="viewer-text">${clean(view.text)}</div>`;if(view.kind==='image')return`<img class="viewer-image" alt="${clean(view.title)}" src="${view.data_url}">`;if(view.kind==='pdf')return`<iframe class="viewer-pdf" title="${clean(view.title)}" src="${view.data_url}"></iframe>`;if(view.kind==='download')return`<div class="download-card"><p>${clean(view.message||'Download this file to open it in a compatible app.')}</p><a class="button button-ink" href="${view.data_url}" download="${clean(view.file_name||view.title)}">Download ${clean(view.file_name||'file')}</a></div>`;return`<div class="notice">${clean(view.message)}</div>`}
async function resource(resourceId,trigger){const studentId=state.activeChild;$('#viewer-content').innerHTML='<div class="viewer-frame"><div class="notice">Loading secure preview...</div></div>';openDialog('viewer-dialog',trigger);try{const view=await api('parentResource',{sessionId:state.sessionId,studentId,resourceId}),body=view.kind==='table'?worksheetTable(view):secureFileBody(view);$('#viewer-content').innerHTML=`<div class="viewer-frame"><span class="watermark">${clean(view.watermark||'Eduwave secure preview')}</span><div class="viewer-title-row"><div><p class="eyebrow">${clean(view.kind==='table'?'Worksheet':'Assigned material')}</p><h2 id="viewer-heading">${clean(view.title)}</h2></div>${view.dueDate?`<span class="status-pill">Due ${clean(date(view.dueDate))}</span>`:''}</div><div id="worksheet-shell">${body}</div>${submissionPanel(view)}</div>`;$('#assignment-submit-form')?.addEventListener('submit',e=>submitAssignment(e,view,studentId));api('parentEvent',{sessionId:state.sessionId,event:'resource_viewed',entityType:'resource',entityId:resourceId,detail:'viewer_open'}).catch(()=>{})}catch(err){$('#viewer-content').innerHTML=`<div class="viewer-frame"><div class="notice">${clean(err.message)}</div></div>`;notify(err.message,'error')}}
function payment(feeId){const activeChild=child();if(!activeChild)return;const f=activeChild.fees.find(x=>x.fee_id===feeId);if(!f)return;const t=$('#payment-template').content.cloneNode(true),form=$('.payment-form',t),card=document.createElement('section');card.className='dash-card';card.innerHTML=`<h4>Payment for ${clean(f.billing_month)}</h4><p class="form-status">Pay by UPI${state.dashboard.upiId?` to ${clean(state.dashboard.upiId)}`:' using the academy instructions'}, then submit the reference.</p>`;form.addEventListener('submit',async e=>{e.preventDefault();const out=$('.form-status',form),button=form.querySelector('[type="submit"]');setStatus(out,'Submitting payment note...');setBusy(button,true,'Submitting...');try{await api('parentPaymentNote',{sessionId:state.sessionId,studentId:state.activeChild,feeId,...Object.fromEntries(new FormData(form))});setStatus(out,'Submitted for academy verification.','success');notify('Payment reference submitted for verification.');await refreshParent()}catch(err){setStatus(out,err.message,'error');notify(err.message,'error')}finally{setBusy(button,false)}});card.append(t);$('#parent-dashboard').prepend(card);card.scrollIntoView({behavior:'smooth'})}
async function refreshParent(){const d=await api('parentDashboard',{sessionId:state.sessionId});state.parent=d.parent;state.dashboard=d.dashboard;renderParent()}
function applyAdmin(){if(state.admin?.sessionId)sessionStorage.setItem(SESSION_KEYS.admin,state.admin.sessionId);$('#admin-auth').classList.add('hidden');$('#admin-app').classList.remove('hidden');renderAdmin()}
async function adminLogout(){const token=state.admin?.sessionId;try{if(token)await api('logout',{sessionId:token})}catch(_){ }sessionStorage.removeItem(SESSION_KEYS.admin);state.admin=null;$('#admin-app').classList.add('hidden');$('#admin-auth').classList.remove('hidden');resetAuth('admin');closeDialog($('#admin-dialog'))}
function options(items,value,label){return`<option value="">Select</option>${items.map(x=>`<option value="${clean(x[value])}">${clean(x[label])}</option>`).join('')}`}
function renderAdmin(){const d=state.admin.data;$('#admin-metrics').innerHTML=[['Approved parents',d.metrics.parents],['Parent requests',d.metrics.pendingParents||0],['Active students',d.metrics.students],['Pending trials',d.metrics.pendingTrials],['Open fees',d.metrics.openFees]].map(x=>`<div><small>${x[0]}</small><b>${x[1]}</b></div>`).join('');adminPanel($('.admin-tabs button.active').dataset.adminTab)}
function adminPanel(tab){const d=state.admin.data,root=$('#admin-content');
 if(tab==='families'){const activeParents=d.parents.filter(x=>x.status==='active'),pendingParents=d.parents.filter(x=>x.status==='pending');root.innerHTML=`<section class="admin-panel"><h3>Your academy families.</h3><p class="form-status">This is the enrolment directory, not an online-status list. Every approved parent is shown together with their linked children.</p><div class="family-summary"><div><small>Approved parents</small><b>${activeParents.length}</b></div><div><small>Currently enrolled</small><b>${d.students.filter(x=>x.enrollment_status==='active').length}</b></div><div><small>Awaiting approval</small><b>${pendingParents.length}</b></div><div><small>Needs linking</small><b>${(d.unlinkedStudents||[]).length}</b></div></div><div class="admin-grid"><article class="admin-card admin-card-wide family-directory-card"><div class="directory-heading"><div><p class="eyebrow">Academy directory</p><h4>Parents and enrolled students</h4></div><label>Find a family<input id="family-search" type="search" placeholder="Search parent, child, email, or class"></label></div><div class="family-directory" id="family-directory"></div>${(d.unlinkedStudents||[]).length?`<div class="unlinked-warning"><b>Students needing a parent link</b>${d.unlinkedStudents.map(x=>`<span>${clean(x.name)} &#8250; Class ${clean(x.class_level)}</span>`).join('')}</div>`:''}</article><article class="admin-card"><h4>Parent account requests</h4><div class="data-list">${pendingParents.map(x=>`<div class="data-line"><b>${clean(x.name)}</b><small>${clean(x.email)} &#8250; ${clean(x.phone||'No phone')}</small><button data-parent-status="active" data-parent-id="${clean(x.parent_id)}">Approve</button><button data-parent-status="denied" data-parent-id="${clean(x.parent_id)}">Deny</button></div>`).join('')||'<div class="notice">No pending parent requests.</div>'}</div></article><article class="admin-card"><h4>Add an approved parent</h4><form id="family-form"><label>Parent name<input required name="name"></label><label>Approved email<input required name="email" type="email"></label><label>WhatsApp number<input name="phone" inputmode="tel"></label><button class="button button-dark">Create parent</button><p class="form-status"></p></form></article><article class="admin-card"><h4>Add a child</h4><form id="student-form"><label>Approved parent<select required name="parentId">${options(activeParents,'parent_id','name')}</select></label><label>Child name<input required name="name"></label><label>Class<input required name="classLevel" placeholder="e.g. 8"></label><div class="form-row"><label>Monthly fee<input name="monthlyFee" inputmode="numeric"></label><label>Due day<input name="dueDay" type="number" min="1" max="28" value="10"></label></div><button class="button button-dark">Create child</button><p class="form-status"></p></form></article></div></section>`;}
 if(tab==='learning'){const studentName=id=>d.students.find(x=>x.student_id===id)?.name||'Student',resourceTitle=id=>d.resources.find(x=>x.resource_id===id)?.title||'Assignment';root.innerHTML=`<section class="admin-panel"><h3>Classroom updates</h3><div class="admin-grid"><article class="admin-card admin-card-wide"><h4>Assignment submissions</h4><div class="submission-review-list">${(d.submissions||[]).map(x=>`<form class="submission-review-form"><input type="hidden" name="submissionId" value="${clean(x.submission_id)}"><div class="submission-review-head"><div><b>${clean(studentName(x.student_id))}</b><small>${clean(resourceTitle(x.resource_id))} &#8250; sent ${clean(date(x.submitted_at))}</small></div><span class="status-pill ${clean(x.status)}">${clean(x.status.replace('_',' '))}</span></div>${x.has_attachment?`<div class="submission-attachment"><div><b>${clean(x.attachment_name||'Uploaded work')}</b><small>${Math.max(1,Math.ceil((x.attachment_size||0)/1024))} KB &#8250; protected academy copy</small></div><button class="button button-outline" type="button" data-submission-file="${clean(x.submission_id)}">Preview uploaded work</button></div>`:''}<div class="answer-preview">${x.answers.map(a=>`<p><b>${clean(a.question||`Row ${a.row}`)}</b><span>${clean(a.answer)}</span></p>`).join('')||(x.has_attachment?'<p>Answers are in the uploaded scan.</p>':'<p>No typed answers; see learner note.</p>')}${x.student_note?`<p><b>Learner note</b><span>${clean(x.student_note)}</span></p>`:''}</div><label>Review outcome<select name="status"><option value="reviewed" ${x.status==='reviewed'?'selected':''}>Reviewed</option><option value="needs_changes" ${x.status==='needs_changes'?'selected':''}>Needs changes</option></select></label><label>Feedback<textarea name="feedback" rows="2" placeholder="Optional feedback for the learner">${clean(x.feedback||'')}</textarea></label><button class="button button-dark">Save review</button><p class="form-status"></p></form>`).join('')||'<div class="notice">Submitted work will appear here.</div>'}</div></article><article class="admin-card"><h4>Exam or class notice</h4><form id="announcement-form"><label>Audience<select name="audience"><option value="all">All parents</option><option value="student">Specific child</option></select></label><label>Child (optional)<select name="studentId">${options(d.students,'student_id','name')}</select></label><label>Title<input required name="title" placeholder="e.g. Maths revision test"></label><label>Message<textarea required name="message" rows="3"></textarea></label><input type="hidden" name="type" value="exam"><button class="button button-dark">Publish notice</button><p class="form-status"></p></form></article><article class="admin-card"><h4>Attendance</h4><form id="attendance-form"><label>Child<select required name="studentId">${options(d.students,'student_id','name')}</select></label><div class="form-row"><label>Date<input required name="sessionDate" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>Subject<input required name="subject"></label></div><label>Status<select name="status"><option>present</option><option>absent</option><option>rescheduled</option></select></label><label>Note<input name="note"></label><button class="button button-dark">Save attendance</button><p class="form-status"></p></form></article><article class="admin-card"><h4>Progress note</h4><form id="progress-form"><label>Child<select required name="studentId">${options(d.students,'student_id','name')}</select></label><div class="form-row"><label>Subject<input required name="subject"></label><label>Score / status<input name="score" placeholder="e.g. 8/10"></label></div><label>Topic<input required name="topic"></label><label>Teacher note<textarea name="note" rows="2"></textarea></label><button class="button button-dark">Add progress note</button><p class="form-status"></p></form></article><article class="admin-card"><h4>Current notices</h4><div class="data-list">${d.announcements.map(x=>`<div class="data-line"><b>${clean(x.title)}</b><small>${clean(x.type)} &#8250; ${clean(x.message)}</small></div>`).join('')||'<div class="notice">Nothing published yet.</div>'}</div></article></div></section>`}
 if(tab==='library')root.innerHTML=libraryPanel(d);
 if(tab==='finance')root.innerHTML=`<section class="admin-panel"><h3>Fees and gentle reminders.</h3><div class="admin-grid"><article class="admin-card"><h4>Generate this month&#8217;s rows</h4><p class="form-status">One fee row per active child with a fee amount. It does not duplicate rows.</p><button class="button button-dark" id="generate-fees">Generate monthly fees</button><p class="form-status"></p></article><article class="admin-card"><h4>Mark payment verified</h4><form id="paid-form"><label>Fee row<select required name="feeId">${options(d.fees,'fee_id','billing_month')}</select></label><label>Reference (optional)<input name="reference"></label><button class="button button-dark">Mark paid</button><p class="form-status"></p></form></article><article class="admin-card"><h4>WhatsApp reminder</h4><form id="reminder-form"><label>Child<select required name="studentId">${options(d.students,'student_id','name')}</select></label><label>Type<select name="type"><option value="fee">Fee reminder</option><option value="general">General update</option></select></label><label>Message<textarea name="message" rows="3" placeholder="Leave blank for a useful default"></textarea></label><button class="button button-dark">Create WhatsApp link</button><p class="form-status"></p></form></article><article class="admin-card"><h4>Fee records</h4><div class="data-list">${d.fees.map(x=>`<div class="data-line"><b>${clean(x.billing_month)} &#8211; Rs ${clean(x.amount)}</b><small>${clean(x.status)} &#8250; due ${clean(x.due_date)} &#8250; ${clean(x.reference||'No reference')}</small></div>`).join('')||'<div class="notice">No fee rows yet.</div>'}</div></article></div></section>`;
 if(tab==='trials')root.innerHTML=`<section class="admin-panel"><h3>Trial requests.</h3><div class="admin-grid"><article class="admin-card"><h4>Pending and recent</h4><div class="data-list">${d.trials.map(x=>`<div class="data-line"><b>${clean(x.child_name||x.childName)} &#8211; ${clean(x.class_level||x.classLevel)}</b><small>${clean(x.parent_name||x.parentName)} &#8250; ${clean(x.phone)} &#8250; ${clean(x.subjects)} &#8250; ${clean(x.status)}</small>${x.status==='pending'?`<button data-approve="${clean(x.trial_id)}">Approve</button><button data-decline="${clean(x.trial_id)}">Decline</button>`:''}</div>`).join('')||'<div class="notice">No trial requests yet.</div>'}</div></article><article class="admin-card"><h4>Simple next step</h4><p class="form-status">Approve a suitable trial, then create or approve the parent email and link the child in Families when they enrol. No raw Drive sharing is required.</p></article></div></section>`;
 bindAdmin();
 if(tab==='families')renderFamilyDirectory();
 if(tab==='library')loadDriveFolders();
}
function driveFileOptions(items){return`<option value="">Choose a file</option>${items.map(item=>`<option value="${clean(item.drive_id)}">${clean(`${item.path?item.path+' / ':''}${item.name}`)}</option>`).join('')}`}
function libraryPanel(d){const found=state.driveItems.length,ready=d.resources.length;return`<section class="admin-panel"><div class="library-heading"><div><p class="eyebrow">Teaching materials</p><h3>Add material without opening Drive.</h3><p>Choose one of the two options below. After the material is added, assign it to a child.</p></div><span class="library-count"><b>${ready}</b> ready to assign</span></div><div class="library-route-grid"><article class="admin-card admin-card-accent library-route"><div class="route-label"><span>Option 1</span><b>Upload a new file</b></div><p>Best for a scanned worksheet, a fresh PDF, or a file saved on this phone or computer.</p><form id="upload-resource-form"><label>Choose the material<input required name="file" type="file" accept=".pdf,.jpg,.jpeg,.png,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.rtf,.txt"></label><small class="field-help">PDF and images open inside the portal. Word, Excel, and PowerPoint files download securely. Maximum 8 MB.</small><label>Title<input required name="title" placeholder="e.g. Fractions practice test"></label><div class="form-row"><label>Subject<input name="subject" placeholder="e.g. Maths"></label><label>Class<input name="classLevel" placeholder="e.g. 8"></label></div><label>What should the child do?<select name="submissionType"><option value="file_upload">Answer in a notebook and upload a scan</option><option value="online_answers">Type answers on the website</option><option value="view_only">Only read or download it</option></select></label><button class="button button-dark">Add this file to Eduwave</button><p class="form-status"></p></form></article><article class="admin-card admin-card-wide library-route drive-route"><div class="route-label"><span>Option 2</span><b>Use a file already in Google Drive</b></div><p>Pick the folder where your material is kept. Eduwave will show its usable files without giving parents the Drive link.</p><div class="drive-step"><span>1</span><div><b>Choose the Drive folder</b><small>Select the folder that contains the worksheet, PDF, Doc, or Sheet.</small></div></div><form id="scan-form"><div class="folder-picker-toolbar"><label>Find a folder<input id="drive-folder-search" type="search" placeholder="Type a folder name"></label><button class="text-button" id="refresh-drive-folders" type="button">Refresh folders</button></div><div class="drive-folder-list" id="drive-folder-list"><div class="notice">Loading your Drive folders...</div></div><input id="selected-drive-folder" name="rootFolderId" type="hidden"><input name="limit" type="hidden" value="250"><p class="selected-folder" id="selected-drive-folder-label">Choose one folder from the list.</p><button class="button button-dark" id="scan-drive-button" disabled>Show files in this folder</button><details class="manual-folder"><summary>Cannot see the folder?</summary><p>Refresh first. The folder-ID option is only a fallback for older shared folders.</p><label>Folder ID<input id="manual-folder-id" placeholder="Paste the folder ID"></label><button class="text-button" id="use-manual-folder" type="button">Use this folder</button></details><p class="form-status"></p></form><div class="drive-file-step ${found?'':'is-empty'}"><div class="drive-step"><span>2</span><div><b>Choose the file to add</b><small>${found?`${found} usable file${found===1?'':'s'} found. Choose one below.`:'Files will appear here after you choose a folder and click “Show files”.'}</small></div></div>${found?`<form id="resource-form"><label>Drive file<select required id="drive-resource-file" name="driveId" class="library-select">${driveFileOptions(state.driveItems)}</select></label><label>Title <small>optional</small><input name="title" placeholder="Keep empty to use the file name"></label><div class="form-row"><label>Subject<input name="subject" placeholder="e.g. Science"></label><label>Class<input name="classLevel" placeholder="e.g. 7"></label></div><label>What should the child do?<select name="submissionType"><option value="file_upload">Answer in a notebook and upload a scan</option><option value="online_answers">Type answers on the website</option><option value="view_only">Only read or download it</option></select></label><button class="button button-dark">Add selected file to Eduwave</button><p class="form-status" id="drive-file-status"></p></form>`:'<div class="drive-empty">No file selection is needed yet.</div>'}</div></article></div><div class="admin-grid library-followup"><article class="admin-card"><div class="route-label"><span>Next step</span><b>Assign material to a child</b></div><p>Only assigned material appears in the parent portal.</p><form id="assign-form"><label>Child<select required name="studentId">${options(d.students,'student_id','name')}</select></label><label>Material<select required name="resourceId">${options(d.resources,'resource_id','title')}</select></label><div class="form-row"><label>Available from<input name="visibleFrom" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>Due date <small>optional</small><input name="dueDate" type="date"></label></div><button class="button button-dark">Assign to this child</button><p class="form-status"></p></form></article><article class="admin-card"><div class="route-label"><span>Your library</span><b>Materials ready to assign</b></div><div class="data-list">${d.resources.map(x=>`<div class="data-line"><b>${clean(x.title)}</b><small>${clean(x.subject||'No subject')} &#8250; ${clean(x.kind)} &#8250; ${clean((x.submission_type||'file_upload').replace('_',' '))}</small></div>`).join('')||'<div class="notice">No material has been added yet. Use either option above.</div>'}</div></article></div></section>`}
function renderFamilyDirectory(){const root=$('#family-directory');if(!root)return;const query=state.familyQuery.toLowerCase(),families=(state.admin.data.families||[]).filter(family=>family.status==='active').filter(family=>{const searchable=[family.name,family.email,family.phone,...family.children.flatMap(child=>[child.name,child.class_level,child.enrollment_status])].join(' ').toLowerCase();return!query||searchable.includes(query)});root.innerHTML=families.map(family=>{const initial=String(family.name||'P').trim().charAt(0).toUpperCase(),activeChildren=family.children.filter(child=>child.enrollment_status==='active');return`<article class="family-record"><header><span class="family-avatar" aria-hidden="true">${clean(initial)}</span><div><h5>${clean(family.name)}</h5><p>${activeChildren.length} currently enrolled student${activeChildren.length===1?'':'s'}</p></div><span class="status-pill ${family.email_verified?'reviewed':'pending'}">${family.email_verified?'Login verified':'First login pending'}</span></header><div class="parent-contact"><a href="mailto:${clean(family.email)}">${clean(family.email)}</a><span>${clean(family.phone||'No WhatsApp number saved')}</span></div><div class="linked-students"><b>Linked students</b>${family.children.length?family.children.map(child=>`<div class="student-directory-row"><div><strong>${clean(child.name)}</strong><small>Class ${clean(child.class_level||'not set')} &#8250; ${clean(child.relationship||'Child')}</small></div><div class="student-directory-meta"><span class="status-pill ${clean(child.enrollment_status)}">${clean(child.enrollment_status||'unknown')}</span><small>${child.monthly_fee?`Rs ${clean(child.monthly_fee)} / month &#8250; due day ${clean(child.due_day||'?')}`:'Fee not set'}</small></div></div>`).join(''):'<div class="family-alert">No child is linked to this approved parent yet.</div>'}</div></article>`}).join('')||'<div class="notice">No approved family matches this search.</div>'}
function bindFamilyDirectory(){$('#family-search')?.addEventListener('input',event=>{state.familyQuery=event.currentTarget.value.trim();renderFamilyDirectory()})}
async function loadDriveFolders(){const list=$('#drive-folder-list');if(!list)return;list.innerHTML='<div class="notice">Loading folders from My Drive...</div>';try{const result=await api('adminDriveFolders',{sessionId:state.admin.sessionId});state.driveFolders=result.folders||[];state.driveFolderId=result.currentFolderId||state.driveFolderId||'';renderDriveFolders();if(state.driveFolderId){const folder=state.driveFolders.find(x=>x.folder_id===state.driveFolderId);selectDriveFolder(state.driveFolderId,folder?.name||'Current master folder')}}catch(err){list.innerHTML=`<div class="notice">${clean(err.message)}</div>`;notify(err.message,'error')}}
function renderDriveFolders(){const list=$('#drive-folder-list');if(!list)return;const query=state.driveFolderQuery.toLowerCase(),folders=(state.driveFolders||[]).filter(x=>!query||String(x.name).toLowerCase().includes(query));list.innerHTML=folders.map(x=>`<button class="drive-folder-option ${x.folder_id===state.driveFolderId?'selected':''}" type="button" data-drive-folder="${clean(x.folder_id)}" data-drive-folder-name="${clean(x.name)}" aria-pressed="${x.folder_id===state.driveFolderId}"><span class="folder-glyph" aria-hidden="true"></span><span><b>${clean(x.name)}</b><small>${x.current?'Current master folder':'My Drive folder'}</small></span><span class="folder-choice">${x.folder_id===state.driveFolderId?'Selected':'Choose'}</span></button>`).join('')||'<div class="notice">No matching folders found.</div>';$$('[data-drive-folder]',list).forEach(button=>button.addEventListener('click',()=>selectDriveFolder(button.dataset.driveFolder,button.dataset.driveFolderName)))}
function selectDriveFolder(id,name){state.driveFolderId=id;const input=$('#selected-drive-folder'),label=$('#selected-drive-folder-label'),button=$('#scan-drive-button');if(input)input.value=id;if(label)label.innerHTML=`Selected: <b>${clean(name||'Drive folder')}</b>`;if(button)button.disabled=!id;$$('[data-drive-folder]').forEach(item=>{const selected=item.dataset.driveFolder===id;item.classList.toggle('selected',selected);item.setAttribute('aria-pressed',String(selected));const choice=$('.folder-choice',item);if(choice)choice.textContent=selected?'Selected':'Choose'})}
function bindDriveFolderPicker(){$('#refresh-drive-folders')?.addEventListener('click',()=>loadDriveFolders());$('#drive-folder-search')?.addEventListener('input',event=>{state.driveFolderQuery=event.currentTarget.value.trim();renderDriveFolders()});$('#use-manual-folder')?.addEventListener('click',()=>{const id=$('#manual-folder-id')?.value.trim();if(!id){notify('Paste the folder ID first.','error');return}selectDriveFolder(id,'Folder entered manually')})}
function bindAdmin(){bindDriveFolderPicker();bindFamilyDirectory();[['family-form','adminCreateFamily'],['student-form','adminCreateStudent'],['announcement-form','adminCreateAnnouncement'],['attendance-form','adminRecordAttendance'],['progress-form','adminRecordProgress'],['scan-form','adminScanDrive'],['resource-form','adminCreateResource'],['assign-form','adminAssignResource'],['paid-form','adminMarkFeePaid'],['reminder-form','adminQueueReminder']].forEach(([id,a])=>{const f=$('#'+id);if(f)f.addEventListener('submit',e=>adminSubmit(e,a))});$('#upload-resource-form')?.addEventListener('submit',adminUploadResource);$$('.submission-review-form').forEach(f=>f.addEventListener('submit',e=>adminSubmit(e,'adminReviewSubmission')));$$('[data-submission-file]').forEach(b=>b.addEventListener('click',()=>submissionFile(b.dataset.submissionFile,b)));$('#generate-fees')?.addEventListener('click',async e=>{const button=e.currentTarget,out=button.nextElementSibling;setStatus(out,'Creating fee rows...');setBusy(button,true,'Creating rows...');try{const r=await api('adminGenerateMonthlyFees',{sessionId:state.admin.sessionId});const message=`Created ${r.created} row(s) for ${r.month}.`;setStatus(out,message,'success');notify(message);await refreshAdmin()}catch(err){setStatus(out,err.message,'error');notify(err.message,'error')}finally{setBusy(button,false)}});$$('[data-approve]').forEach(b=>b.addEventListener('click',()=>trialUpdate(b.dataset.approve,'approved')));$$('[data-decline]').forEach(b=>b.addEventListener('click',()=>trialUpdate(b.dataset.decline,'declined')));$$('[data-parent-status]').forEach(b=>b.addEventListener('click',()=>parentStatus(b.dataset.parentId,b.dataset.parentStatus)))}
async function adminSubmit(e,action){e.preventDefault();const f=e.currentTarget,out=$('.form-status',f),button=f.querySelector('[type="submit"]');if(!f.reportValidity())return;setStatus(out,action==='adminScanDrive'?'Finding usable files...':'Saving...');setBusy(button,true,action==='adminScanDrive'?'Finding files...':'Saving...');try{const result=await api(action,{sessionId:state.admin.sessionId,...Object.fromEntries(new FormData(f))});if(action==='adminScanDrive'){state.driveItems=result.files||await api('adminDriveItems',{sessionId:state.admin.sessionId});const found=result.found??state.driveItems.length,message=found?`Found ${found} usable file${found===1?'':'s'} in ${result.folderName||'the selected folder'}. Choose one below.`:`No usable files were found in ${result.folderName||'that folder'}. Try another folder.`;notify(message,found?'success':'error');await refreshAdmin();setStatus($('#drive-file-status')||$('#scan-form .form-status'),message,found?'success':'error');$('#drive-resource-file')?.focus();return}else if(action==='adminQueueReminder'&&result.whatsappUrl){setStatus(out,'Reminder queued. Opening WhatsApp...','success');notify('Reminder link is ready.');window.open(result.whatsappUrl,'_blank','noopener')}else if(action==='adminCreateResource'){setStatus(out,'Material added. Assign it to a child below.','success');notify('Material added to Eduwave.')}else{setStatus(out,'Saved.','success');notify('Academy record saved.')}f.reset();await refreshAdmin()}catch(err){setStatus(out,err.message,'error');notify(err.message,'error')}finally{setBusy(button,false)}}
async function adminUploadResource(event){event.preventDefault();const form=event.currentTarget,out=$('.form-status',form),button=form.querySelector('[type="submit"]');if(!form.reportValidity())return;setStatus(out,'Adding the file securely...');setBusy(button,true,'Adding file...');try{const fd=new FormData(form),file=await encodeFile(fd.get('file')),payload=Object.fromEntries(fd);delete payload.file;await api('adminUploadResource',{sessionId:state.admin.sessionId,...payload,file});setStatus(out,'Material added. Assign it to a child below.','success');notify('Material added to Eduwave.');form.reset();await refreshAdmin()}catch(err){setStatus(out,err.message,'error');notify(err.message,'error')}finally{setBusy(button,false)}}
async function submissionFile(submissionId,trigger){$('#viewer-content').innerHTML='<div class="viewer-frame"><div class="notice">Loading protected submission...</div></div>';openDialog('viewer-dialog',trigger);try{const view=await api('adminSubmissionFile',{sessionId:state.admin.sessionId,submissionId});$('#viewer-content').innerHTML=`<div class="viewer-frame"><span class="watermark">Academy review copy</span><div class="viewer-title-row"><div><p class="eyebrow">Student submission</p><h2 id="viewer-heading">${clean(view.title)}</h2></div></div>${secureFileBody({...view,file_name:view.title,message:'Download this submitted file to review it.'})}</div>`}catch(err){$('#viewer-content').innerHTML=`<div class="viewer-frame"><div class="notice">${clean(err.message)}</div></div>`;notify(err.message,'error')}}
async function parentStatus(parentId,statusValue){try{await api('adminSetParentStatus',{sessionId:state.admin.sessionId,parentId,status:statusValue});notify(`Parent account ${statusValue==='active'?'approved':'denied'}.`);await refreshAdmin()}catch(err){notify(err.message,'error')}}
async function trialUpdate(id,statusValue){try{await api('adminApproveTrial',{sessionId:state.admin.sessionId,trialId:id,status:statusValue});notify(`Trial request ${statusValue}.`);await refreshAdmin()}catch(err){notify(err.message,'error')}}async function refreshAdmin(){state.admin.data=await api('adminDashboard',{sessionId:state.admin.sessionId});renderAdmin()}
})();
